## 创建完成的 prime.py

```python
import sys

def is_prime(n):
    """Check if n is a prime number."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    # Check odd divisors up to sqrt(n)
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def main():
    if len(sys.argv) != 2:
        print("Usage: python3 prime.py <integer>")
        sys.exit(1)

    try:
        num = int(sys.argv[1])
        if is_prime(num):
            print("prime")
        else:
            print("composite")
    except ValueError:
        print("Error: Please provide a valid integer")
        sys.exit(1)

if __name__ == "__main__":
    main()
```

